mapper.update:
{CALL
    DECLARE
        v_sql varchar2(500);
    BEGIN
        v_sql := 'CREATE SEQUENCE ${tableName}_SEQ START WITH 1 MAXVALUE 99999999 MINVALUE 1 CYCLE CACHE 20 NOORDER';
        execute immediate v_sql;

        v_sql := 'CREATE INDEX ${tableName}_IDX1 ON ${tableName}(MSG_STATUS, REQ_CH, TRAFFIC_TYPE, REQ_DATE)';
        execute immediate v_sql;

        v_sql := 'CREATE INDEX ${tableName}_IDX2 ON ${tableName}(PHONE)';
        execute immediate v_sql;

        v_sql := 'CREATE INDEX ${tableName}_IDX3 ON ${tableName}(DONE_CODE, REQ_DATE)';
        execute immediate v_sql;
    END
}

{CALL
    DECLARE
        v_sql varchar2(500);
    BEGIN
        v_sql := 'CREATE INDEX ${tableName}_IDX1 ON ${tableName}(PHONE)';
        execute immediate v_sql;

        v_sql := 'CREATE INDEX ${tableName}_IDX2 ON ${tableName}(DONE_CODE, REQ_DATE)';
        execute immediate v_sql;
    END
}

UPDATE ${tableName}
SET
    MSG_STATUS = CASE WHEN MSG_STATUS = 'complete' THEN MSG_STATUS ELSE #{parameter.messageStatus} END
    , REQ_CH = #{parameter.requestChannel}
    , ROUTE_INFO = #{parameter.routeId}
    , SENT_DATE = TO_DATE(#{parameter.sentDate}, 'YYYYMMDDHH24MISS')
    , DONE_CH = #{parameter.doneChannel}
    , DONE_PRODUCT = #{parameter.doneProduct}
    , DONE_DATE = TO_DATE(#{parameter.doneDate}, 'YYYYMMDDHH24MISS')
    , DONE_CODE = #{parameter.doneCode}
    , DONE_CODE_DESC = #{parameter.doneCodeDescription}
    , DONE_FB_DETAIL = #{parameter.doneFallbackDetail}
    , DONE_TELCO = #{parameter.doneTelco}
WHERE
    CLIENT_KEY IS NULL
    CLIENT_KEY = #{parameter.key}

DELETE FROM ${tableName}
WHERE
    CLIENT_KEY IS NULL
    CLIENT_KEY = #{parameter.key}
